    mouzhangrang:{id:'mouzhangrang',name:'张让',hp:3,gender:'male',faction:'群',source:'https://www.sanguosha.com/hero/697',skills:[
      {name:'赂存',active:true,text:'每轮基本牌、普通锦囊牌各限一次，视为使用一张有角色目标且未以此技能使用过的牌。结算后，目标中手牌最多的一名角色将一张手牌置于你武将牌上作为“赂”。每个回合结束时随机弃置一张“赂”，每轮首次以此法弃置后摸一张牌。'},
      {name:'蜕生',text:'限定技，准备阶段或自己濒死时，重置赂存已使用牌名；选择将所有手牌置为“赂”，或随机获得弃牌堆中至多X张此前赂存使用过牌名的牌，然后回复1点体力。X为当前轮数。'}
    ]},
    wolongfengchu:{id:'wolongfengchu',name:'卧龙凤雏',hp:4,gender:'male',faction:'蜀',source:'https://www.sanguosha.com/hero/475',skills:[
      {name:'游龙',active:true,text:'转换技，阳：普通锦囊；阴：基本牌。每轮每种状态各限一次，废除一个装备栏，视为使用一张本状态且未以此技能使用过的牌。初始为阳。'},
      {name:'鸾凤',text:'限定技，体力上限不小于你的角色濒死时，可令其回复至3点体力，恢复所有废除装备栏，并将手牌摸至6-X张，X为恢复栏数。若救自己，重置游龙已使用牌名。'}
    ]},
